#!/usr/bin/env python3
"""Writes migration 0021: the 30 core Toolbox Talks. Edit the talks here, then re-run to produce a NEW numbered migration if they change later
(never edit an applied migration). General guidance only: it needs professional review and does not replace a business's own risk assessments."""
import sys
HS, FIRE, WELL, RESP, IND = 'Health & Safety', 'Fire Safety', 'Wellbeing', 'Workplace Responsibilities', 'Industry Specific'
T = [
# ---- Health & Safety ----
(HS, 'Slips, Trips and Falls', 8, 'The most common cause of injury at work is also one of the easiest to prevent.',
 ['Clean up spills straight away, or put up a wet floor sign and report it until it is dealt with.', 'Keep walkways, corridors and stairs clear. Do not leave boxes, cables or bags where people walk.', 'Wear sensible footwear with good grip, and take extra care when floors are wet, such as on rainy days.', 'Report loose carpet, damaged flooring, broken handrails and poor lighting rather than working around them.', 'Do not carry loads you cannot see over. Use the handrail on stairs and never run.'],
 ['Where on our site is the floor most likely to be wet or cluttered?', 'What is one thing we could change this week to make a walkway safer?']),
(HS, 'Manual Handling', 10, 'Lifting and carrying causes a lot of back and joint injuries. Planning the job protects you.',
 ['Think before you lift: avoid it if you can, use a trolley or ask for help, and reduce the load if you cannot avoid it.', 'Check the Task, the Individual, the Load and the Environment: how far, how heavy, how awkward, and is the route clear?', 'Keep the load close to your body, bend your knees, keep your back straight and avoid twisting.', 'Break up large or heavy loads where possible and share the lift with a colleague, agreeing who leads.', 'Do not lift if you are injured or unwell, and report any pain or strain early.'],
 ['What do we lift or carry most often here, and could we use equipment instead?', 'How do you let a colleague know you need a hand?']),
(HS, 'Working at Height', 12, 'A fall from a ladder or step can be serious, even from a low height.',
 ['Avoid working at height if the job can be done another way, for example with an extension pole.', 'Use the right equipment for the job. Ladders are for short, low-risk tasks, not long jobs.', 'Check ladders and steps before each use: feet, rungs, locks and condition. Never use damaged equipment.', 'Keep three points of contact, do not overreach, and never stand on the top step.', 'Set the equipment on firm, level ground, and keep other people away from the area below.'],
 ['What jobs here involve going up a ladder or steps?', 'Who checks that our ladders are in good condition, and how often?']),
(HS, 'Electrical Safety at Work', 10, 'Most electrical accidents come from damaged equipment or misuse. A quick look before use makes a difference.',
 ['Look at plugs, cables and equipment before you use them. Do not use anything damaged, hot or burning-smelling.', 'Do not overload sockets or daisy-chain extension leads. Unroll extension reels fully.', 'Keep liquids away from electrical equipment, and never touch electrics with wet hands.', 'Do not attempt repairs yourself. Switch off, unplug if it is safe, label it as faulty and report it.', 'Portable appliances are usually tested and labelled at intervals, and fixed wiring is inspected periodically. Report anything that looks overdue.'],
 ['Do we have anywhere that looks overloaded or has trailing cables?', 'What would you do if you saw sparks from a socket?']),
(HS, 'Using Work Equipment Safely', 10, 'Machines and tools are safe when they are used as intended, by trained people, with guards in place.',
 ['Only use equipment you have been trained and authorised to use.', 'Read the instructions and follow them, and use guards and safety devices. Never remove or bypass them.', 'Check equipment before use, and report faults at once. Take faulty equipment out of use and label it.', 'Isolate equipment from the power before cleaning, clearing a jam or adjusting it.', 'Keep long hair, loose clothing and jewellery away from moving parts.'],
 ['What equipment here are you not fully confident using?', 'How do we tag out equipment that is faulty?']),
(HS, 'Hazardous Substances (COSHH)', 12, 'Cleaning products, paints, solvents and dusts can harm health if they are not used and stored properly.',
 ['Look at the label and the safety data sheet before you use a product, and follow what it says.', 'Learn the hazard symbols. They show if a product is corrosive, flammable, toxic or irritating.', 'Keep products in their original, labelled containers. Never decant into drinks bottles or unlabelled containers.', 'Wear the protective equipment the sheet asks for, wash your hands afterwards, and never mix products.', 'Store products securely and report spills, leaks or any symptoms such as skin irritation or breathing problems.'],
 ['Where are the safety data sheets kept on this site?', 'Which product here would be most harmful if it were used the wrong way?']),
(HS, 'Reporting Accidents and Near Misses', 8, 'Reporting what went wrong, or nearly did, is how we stop it happening to someone else.',
 ['Report every accident, injury and near miss, however small it seems, as soon as possible.', 'Record it in the accident book or the way your workplace asks, with facts: what, where, when and who.', 'Near misses are free lessons. A trip that did not cause an injury this time might next time.', 'Reporting is about fixing the problem, not blaming the person.', 'Some serious incidents and illnesses must be reported to the HSE by your employer. Tell your manager straight away.'],
 ['Do you know where the accident book is kept?', 'What near miss have you seen that nobody reported?']),
(HS, 'Personal Protective Equipment (PPE)', 8, 'PPE is the last line of defence. It only works when it is the right kind, fitted well and worn.',
 ['PPE is used when other ways of controlling a risk are not enough. It does not remove the hazard.', 'Your employer must provide the right PPE free of charge, and you must wear it as instructed.', 'Check it before each use. Damaged, dirty or out-of-date PPE should be replaced, not used.', 'Make sure it fits. Poorly fitting gloves, masks or boots can cause as many problems as they solve.', 'Store it clean and dry, and tell your manager if you need a different size or type.'],
 ['What PPE do we need for the jobs we do here?', 'What makes PPE uncomfortable, and what could we do about it?']),
(HS, 'Lone Working', 8, 'Working alone is not unsafe by itself, but help is further away if something goes wrong.',
 ['Make sure someone knows where you are, what you are doing and when you will finish.', 'Agree a check-in routine, and what happens if you do not check in on time.', 'Carry a charged phone and know how to call for help. Check you have signal where you are working.', 'Never take a risk because nobody is watching. Stop if the job is not safe to do alone.', 'Report any threat, aggressive visitor or feeling of being unsafe, and know your escape route.'],
 ['Who here works alone, and when?', 'How would we know if a lone worker needed help?']),
# ---- Fire Safety ----
(FIRE, 'Preventing Fires', 10, 'Most fires start from something simple that could have been stopped. Prevention is everyone’s job.',
 ['Keep ignition sources away from anything that burns. Check heaters, cookers and electrical equipment, and switch off at the end of the day.', 'Do not overload sockets, and report hot, damaged or burning-smelling equipment.', 'Keep waste and packaging away from buildings and electrics. Empty bins regularly.', 'Store flammable liquids and gases properly, in small quantities, away from heat.', 'Follow the smoking rules, and make sure doors and windows are secured at closing time to reduce the risk of arson.'],
 ['What is the most likely cause of a fire on this site?', 'What do we do at the end of the day to reduce the risk?']),
(FIRE, 'If You Discover a Fire', 10, 'Knowing what to do before it happens saves time and lives.',
 ['Raise the alarm straight away by shouting a warning and using the nearest call point.', 'Call 999 and ask for the fire and rescue service. Give the address and say what is on fire.', 'Only tackle a very small fire if you are trained, it is safe to do so, and you have a clear escape route behind you.', 'Leave by the nearest safe exit and close doors behind you if you can. Do not use lifts.', 'Go to the assembly point, report to whoever is taking the roll call, and do not go back in for any reason.'],
 ['Where is the nearest alarm call point to where you work?', 'What is the sound of our fire alarm, and what do you do when you hear it?']),
(FIRE, 'Fire Exits, Escape Routes and Assembly Points', 8, 'A fire exit only helps if people can get to it, open it, and know where to go next.',
 ['Keep fire exits and escape routes clear at all times. Never store anything in corridors, on stairs or in front of doors.', 'Exit doors must open easily from the inside without a key while people are in the building.', 'Know at least two ways out of where you work, and the way to the assembly point.', 'Report blocked exits, missing or unlit signs, and anything that would slow people down.', 'Tell your manager if someone you work with, or a regular visitor, would need help to get out.'],
 ['Can everyone here name the assembly point?', 'What is the one thing most likely to block our exits?']),
(FIRE, 'Fire Extinguishers: Know Your Types', 8, 'The wrong extinguisher on the wrong fire can make things worse. Know what is on your site.',
 ['Extinguishers have a red body with a colour band showing the type: water, foam, powder, carbon dioxide or wet chemical.', 'Water is for paper, wood and fabric. It must never be used on electrical fires or burning fat or oil.', 'Carbon dioxide is commonly used for electrical fires. Wet chemical is made for cooking oils and fats.', 'Only use one if you have been trained, the fire is small and you can leave quickly. If in doubt, get out.', 'Report extinguishers that are missing, blocked, damaged or past their service date.'],
 ['What types of extinguisher do we have, and where are they?', 'Which fire here would need which type?']),
(FIRE, 'Fire Alarms and Emergency Lighting', 8, 'Alarms and emergency lights are tested regularly. You can help by noticing when something is not right.',
 ['The alarm is commonly tested weekly, and emergency lights are commonly checked monthly. Know when this happens at your site.', 'Do not cover, block or interfere with smoke detectors, call points or sounders.', 'Report any alarm that does not sound, a panel showing a fault, or an emergency light that is out or flickering.', 'Never ignore an alarm because you think it is a test or a false alarm. Treat every alarm as real unless you have been told otherwise.', 'Take part in drills and learn what the signs and symbols mean.'],
 ['Who tests the alarm here, and where is the record kept?', 'Have you seen an emergency light that did not look right?']),
(FIRE, 'Fire Doors: Keep Them Shut', 8, 'A closed fire door can hold back fire and smoke for long enough for people to escape.',
 ['Fire doors only work if they are closed. Never wedge or prop one open.', 'If a door is held open, it should use an approved hold-open device that releases when the alarm sounds.', 'Check the door closes fully by itself, the seals and gaps look right, and the closer is working.', 'Do not damage doors or glass, and do not remove or paint over seals.', 'Report damaged, sticking or missing-closer fire doors at once.'],
 ['Which doors here are fire doors?', 'What stops people from closing them, and what could we do about it?']),
# ---- Wellbeing ----
(WELL, 'Stress and Mental Wellbeing', 10, 'Everyone has pressure sometimes. Spotting it early and talking about it helps.',
 ['Stress shows up differently for different people: tiredness, irritability, trouble concentrating, or avoiding work.', 'Talking helps. Speak to your manager, a colleague you trust, or someone outside work.', 'Managers should listen, look at workload and what can be changed, and follow up.', 'Look after the basics: breaks, food, water, sleep and time away from work.', 'If you are struggling, help is available. The Samaritans are free on 116 123, day or night.'],
 ['What is one thing that makes work harder than it needs to be?', 'How can we make it easier to say when we are struggling?']),
(WELL, 'Working in Hot and Cold Conditions', 8, 'Temperature affects how we feel and how safely we work.',
 ['In the heat: drink water regularly, take breaks in the shade or somewhere cool, and wear light, breathable clothing.', 'Signs of heat illness include headache, dizziness, nausea and heavy sweating. Stop, cool down and get help.', 'In the cold: wear layers, keep hands and feet warm, and take warm drinks and breaks.', 'Take extra care on icy ground and in poor weather. Report ice, flooding or leaks.', 'Tell your manager if your workplace is regularly too hot or too cold to work comfortably.'],
 ['Where on this site do people struggle with the temperature?', 'What do we do on the hottest and coldest days?']),
(WELL, 'Display Screen Equipment', 8, 'Setting up your workstation properly prevents aches, eye strain and long-term problems.',
 ['Sit with your back supported, feet flat, and elbows level with the desk.', 'Place the screen at arm’s length with the top of the screen around eye level.', 'Take short, frequent breaks from the screen. A few minutes away every hour helps.', 'Keep your keyboard and mouse close, wrists straight, and the desk clear for room to move.', 'Tell your manager about pain, tingling or eye strain. You can ask for a workstation assessment.'],
 ['How is your own desk set up right now?', 'What would make your workstation more comfortable?']),
(WELL, 'Tiredness and Fatigue', 8, 'Being tired makes mistakes, accidents and bad decisions more likely.',
 ['Tiredness slows reactions and makes it harder to concentrate, so it increases risk, especially driving, using equipment and working at height.', 'Signs include yawning, heavy eyes, mistakes, and drifting off. Take them seriously.', 'Caffeine is not a fix. Rest, food, water and a short break help more.', 'Plan your sleep around shifts and early starts, and avoid long hours back to back where you can.', 'Tell your manager if you are too tired to work safely or to drive home.'],
 ['When are you most tired at work?', 'What would you do if a colleague looked too tired to carry on safely?']),
(WELL, 'Good Hygiene and Preventing Infection', 8, 'Simple habits stop germs spreading between colleagues, customers and visitors.',
 ['Wash your hands with soap and water for at least 20 seconds: after the toilet, before eating, after handling waste and when they are dirty.', 'Cover coughs and sneezes with a tissue, bin it and wash your hands.', 'Clean regularly touched surfaces such as door handles, switches, taps and shared equipment.', 'Cover cuts and grazes with a waterproof dressing.', 'If you have had sickness or diarrhoea, stay away until you have been clear for 48 hours, and tell your manager.'],
 ['Where are the handwashing facilities here, and are they well stocked?', 'What are the most touched surfaces in our workplace?']),
# ---- Workplace Responsibilities ----
(RESP, 'Health and Safety: Everyone’s Responsibility', 10, 'Employers have duties, and so do the people who work for them.',
 ['Your employer must provide a safe place to work, safe equipment, training, and information about the risks.', 'You must take reasonable care of your own safety and of others affected by what you do.', 'You must cooperate with your employer, follow instructions and training, and use equipment as intended.', 'You must not interfere with or misuse anything provided for health and safety.', 'You can, and should, speak up about anything that looks unsafe.'],
 ['What is one safety rule here that people sometimes skip?', 'Who do you tell when you spot a hazard?']),
(RESP, 'First Aid: Who and Where', 8, 'In an emergency, the first few minutes matter. Know who can help and where the equipment is.',
 ['Know who the first aiders or appointed persons are, and how to reach them quickly.', 'Know where the first aid kit is, and tell someone when items are used or out of date.', 'In a serious emergency, call 999 first, then fetch help.', 'Do not give medication unless you are trained and authorised. Stay with the person until help arrives.', 'Record every incident that needs first aid, and tell your manager.'],
 ['Who are our first aiders, and where is the first aid kit?', 'What would you do if a colleague collapsed in front of you?']),
(RESP, 'Visitors and Contractors on Site', 8, 'People who do not know the building need to be kept safe and need to keep our site safe.',
 ['Everyone signs in and out, so we know who is on site if there is an emergency.', 'Brief visitors and contractors on the fire alarm, exits and assembly point.', 'Contractors should have a clear scope of work, and where needed a permit to work for jobs such as hot work or roof access.', 'Check the asbestos register and site information with contractors before any work that could disturb the building.', 'Escort visitors if they are not familiar with the site, and challenge politely anyone who is not signed in.'],
 ['What do visitors need to know when they arrive here?', 'What would you do if you saw a stranger in a staff area?']),
(RESP, 'Security and Locking Up', 8, 'Good security protects people, stock and the building, and reduces the risk of fire.',
 ['Keep keys, fobs and alarm codes secure and do not share them. Report anything lost straight away.', 'At closing, check all areas, switch off non-essential equipment, close windows and fire doors and lock up.', 'Make sure nobody is left inside, especially in toilets, stores and back rooms.', 'Set the alarm as you have been trained, and know what to do if it activates.', 'Report suspicious people or activity and any damage, and never put yourself at risk.'],
 ['What is the closing routine here, and is it written down?', 'What would you do if you found a door open in the morning?']),
(RESP, 'Treating Each Other with Respect', 10, 'A safe workplace is also one where people feel respected and able to speak up.',
 ['Everyone has the right to be treated with dignity. Bullying, harassment and discrimination are not acceptable.', 'Banter is only banter if everyone is comfortable with it. If it hurts, it is a problem.', 'If someone upsets you, tell them if you feel able to, or tell your manager. You will be taken seriously.', 'If you see it happening to someone else, you can support them and report it.', 'Know your workplace policy and who you can speak to confidentially.'],
 ['What does a respectful team look like here?', 'Who would you go to if you needed to raise a concern?']),
# ---- Industry Specific (property compliance) ----
(IND, 'Legionella and Water Safety', 10, 'Legionella bacteria can grow in water systems that are not managed. It can cause serious illness.',
 ['The bacteria grow in water kept between about 20 and 45 degrees, especially where it is still.', 'Little-used taps and showers are flushed regularly (commonly weekly) so water does not stand still. Follow your site’s schedule and record it.', 'Water temperatures are checked and recorded. Hot water should be hot and cold water should be cold.', 'Do not remove, change or disinfect showerheads or taps unless you have been told to.', 'Report water that is discoloured, smelly, too warm or cold, and any leaks or dead ends in pipework.'],
 ['Which taps or showers here are used least?', 'Where is our Legionella risk assessment, and who looks after it?']),
(IND, 'Asbestos Awareness', 10, 'Buildings built before 2000 may contain asbestos. It is safe when it is undisturbed and dangerous when it is damaged.',
 ['Asbestos was used in many materials such as ceiling tiles, insulation, boards and pipe lagging.', 'Look at the asbestos register before any work that could drill into, cut or break the building.', 'If you are not sure whether a material contains asbestos, treat it as if it does. Stop work and report it.', 'Never sweep, brush or vacuum suspected debris. Keep other people away from the area.', 'Report any damage to materials, and never remove asbestos unless you are licensed and trained.'],
 ['Do you know where the asbestos register is kept?', 'What work here could disturb the fabric of the building?']),
(IND, 'Gas Safety and Gas Leaks', 8, 'Gas is safe when it is installed and maintained properly. Everyone should know what to do if something goes wrong.',
 ['If you smell gas: do not use switches, phones or flames. Open doors and windows and turn off at the meter if it is safe.', 'Leave the building and call the National Gas Emergency Service on 0800 111 999. It is free, and it is open at any time.', 'Only Gas Safe registered engineers should work on gas equipment.', 'Know the signs of carbon monoxide poisoning: headache, dizziness, nausea and tiredness. Alarms should be fitted where needed.', 'Report faulty gas appliances, yellow or lazy flames and sooty marks straight away.'],
 ['Where is the gas shut-off here?', 'When was gas equipment here last checked, and where is the record?']),
(IND, 'Emergency Shut-offs and Contacts', 8, 'In an emergency, being able to isolate the gas, water or power quickly can prevent serious damage and harm.',
 ['Know where the gas, water and electric shut-offs are for your site, and who is allowed to use them.', 'Know where the assembly point is and who the key contacts are, such as keyholders and managers.', 'Keep this information up to date. It is stored under Emergency Information in your passport.', 'Never try to isolate anything if it is not safe to do so. Leave and call for help.', 'Put the numbers for emergency services, your keyholders and your contractors where they can be found quickly.'],
 ['Can everyone here find the water, gas and electric shut-offs?', 'Is our contact list correct today?']),
(IND, 'Pest Control: Spotting and Reporting', 8, 'Pests can damage property, spoil stock and spread disease. Early reporting makes control easier.',
 ['Signs include droppings, gnaw marks, nests, smears, noises and sightings. Report anything you see.', 'Keep food and waste in sealed containers and clean up spills and crumbs.', 'Keep doors and windows closed and report gaps, holes and damaged seals around pipes and doors.', 'Do not put down poison or traps yourself. Leave it to your pest control contractor.', 'Keep a record of sightings and visits, and share it with the contractor.'],
 ['Where on this site would pests be most likely to get in?', 'Who do we report a sighting to?']),
]
assert len(T) == 30, len(T)
def q(s): return '$q$' + s + '$q$'
def arr(xs): return 'array[' + ', '.join(q(x) for x in xs) + ']::text[]'
out = ['-- The 30 core Toolbox Talks (generated by supabase/tools/make_talks_seed.py). General guidance only: it needs professional review.']
out.append('insert into toolbox_talks(code, category, title, summary, points, discuss, minutes, sort) values')
rows = []
for i, (cat, title, mins, summ, pts, dis) in enumerate(T, 1):
    rows.append('  (%s, %s, %s, %s, %s, %s, %d, %d)' % (q('tt%02d' % i), q(cat), q(title), q(summ), arr(pts), arr(dis), mins, i))
out.append(',\n'.join(rows) + ';')
open(sys.argv[1] if len(sys.argv) > 1 else '/dev/stdout', 'w').write('\n'.join(out) + '\n')
